import 'dart:convert';
import 'dart:io';
import 'dart:typed_data';

import 'package:crypto/crypto.dart';
import 'package:flutter_test/flutter_test.dart';
import 'package:anj_cloud/core/gateway/der.dart';
import 'package:anj_cloud/core/gateway/device_crypto.dart';

import 'openssl_cli.dart';

/// The in-process device crypto (spec #28 U1) against OpenSSL: committed
/// golden vectors made by the pre-U1 client commands (fixtures/device_crypto,
/// regenerated by generate.sh), plus live comparisons with the OpenSSL CLI,
/// which only tests run.
void main() {
  const crypto = DartDeviceCrypto();
  const golden = 'test/fixtures/device_crypto';
  final expected = jsonDecode(
    File('$golden/expected.json').readAsStringSync(),
  ) as Map<String, dynamic>;
  String read(String name) => File('$golden/$name').readAsStringSync();
  DateTime opensslDate(String iso) =>
      DateTime.parse(iso.replaceFirst(' ', 'T'));

  group('golden vectors from OpenSSL', () {
    test('a pre-U1 CSR yields the fingerprint OpenSSL computed', () {
      // Pre-U1 CSRs in profiles still match their key, so prepare() keeps
      // them. (Private keys are never committed; key loading is compared
      // live below.)
      expect(expected['csr_fingerprint'], expected['key_fingerprint']);
      expect(
        keyFingerprint(crypto.requestPublicKeyInfo(read('legacy_device.csr'))),
        expected['csr_fingerprint'],
      );
    });

    test('certificate fingerprint, subject and expiry equal OpenSSL', () {
      final certificates = expected['certificates'] as Map<String, dynamic>;
      for (final MapEntry(key: name, value: fields) in certificates.entries) {
        final values = fields as Map<String, dynamic>;
        final certificate = crypto.certificate(read('$name.crt'));
        expect(
          keyFingerprint(certificate.publicKeyInfo),
          values['fingerprint'],
          reason: name,
        );
        expect(certificate.subject, values['subject'], reason: name);
        final notAfter = opensslDate(values['not_after'] as String);
        expect(certificate.notAfter, notAfter, reason: name);
        expect(certificate.notAfter.isUtc, isTrue, reason: name);
        // The manifest's certificateExpires string is unchanged.
        expect(
          certificate.notAfter.toIso8601String(),
          notAfter.toIso8601String(),
          reason: name,
        );
      }
    });

    test('the fixture leaves verify against the fixture issuer', () async {
      final anchors = crypto.certificates(read('issuer.crt'));
      for (final name in ['leaf_utc', 'leaf_generalized']) {
        await crypto.verifyClientCertificate(
          crypto.certificate(read('$name.crt')),
          anchors,
          at: DateTime.now().toUtc(),
        );
      }
      await expectLater(
        crypto.verifyClientCertificate(
          crypto.certificate(read('leaf_utc.crt')),
          anchors,
          at: DateTime.utc(2050),
        ),
        throwsA(isA<CertificateRejected>()),
      );
    });
  });

  group('live comparison with the OpenSSL CLI', () {
    late Directory dir;
    String path(String name) => '${dir.path}/$name';
    Future<String> fingerprintByOpenssl(List<int> pem, String command) async {
      final public = command == 'pkey'
          ? await openssl(['pkey', '-pubout'], pem)
          : await openssl([command, '-pubkey', '-noout'], pem);
      return sha256
          .convert(await openssl(['pkey', '-pubin', '-outform', 'DER'], public))
          .toString();
    }

    late String legacyKey;
    setUpAll(() async {
      dir = Directory.systemTemp.createTempSync('anj-crypto-');
      // An existing Linux device's key, made as the pre-U1 client made it.
      legacyKey = utf8.decode(
        await openssl([
          'genpkey',
          '-algorithm',
          'EC',
          '-pkeyopt',
          'ec_paramgen_curve:P-256',
        ]),
      );
    });
    tearDownAll(() => dir.deleteSync(recursive: true));

    test(
      'an existing openssl genpkey key loads with the same fingerprint',
      () async {
        for (var i = 0; i < 4; i++) {
          final key = i == 0
              ? legacyKey
              : utf8.decode(
                  await openssl([
                    'genpkey',
                    '-algorithm',
                    'EC',
                    '-pkeyopt',
                    'ec_paramgen_curve:P-256',
                  ]),
                );
          expect(
            keyFingerprint(await crypto.publicKeyInfo(key)),
            await fingerprintByOpenssl(utf8.encode(key), 'pkey'),
          );
        }
      },
    );

    test('generated keys have OpenSSL genpkey layout and fingerprint', () async {
      final legacy = pemBlocks(legacyKey).single.$2;
      for (var i = 0; i < 8; i++) {
        final key = await crypto.generateKey();
        final blocks = pemBlocks(key);
        expect(blocks.single.$1, 'PRIVATE KEY');
        final der = blocks.single.$2;
        // Same PKCS#8/ECPrivateKey framing byte for byte; only d and Q differ.
        expect(der.length, legacy.length);
        expect(der.sublist(0, 36), legacy.sublist(0, 36));
        expect(der.sublist(68, 73), legacy.sublist(68, 73));
        expect(key, pemEncode('PRIVATE KEY', der));
        await openssl(['pkey', '-check', '-noout'], utf8.encode(key));
        expect(
          keyFingerprint(await crypto.publicKeyInfo(key)),
          await fingerprintByOpenssl(utf8.encode(key), 'pkey'),
        );
        // dart:io's TLS (BoringSSL) takes it for mutual TLS.
        SecurityContext().usePrivateKeyBytes(utf8.encode(key));
      }
    });

    test('CSR equals openssl req -new apart from the signature, and verifies', () async {
      final profile = expected['profile'] as String;
      final ours = await crypto.certificationRequest(
        legacyKey,
        commonName: profile,
      );
      Uint8List info(String pem) =>
          Der.decode(pemBlocks(pem).single.$2).items()[0].encoded;
      // The pre-U1 command: openssl req -new -sha256 -key - -subj /CN=<id>.
      final theirs = utf8.decode(
        await openssl([
          'req',
          '-new',
          '-sha256',
          '-key',
          '/dev/stdin',
          '-subj',
          '/CN=$profile',
        ], utf8.encode(legacyKey)),
      );
      expect(info(ours), info(theirs));
      final bytes = utf8.encode(ours);
      await openssl(['req', '-verify', '-noout'], bytes);
      expect(
        utf8
            .decode(
              await openssl([
                'req',
                '-noout',
                '-subject',
                '-nameopt',
                'RFC2253',
              ], bytes),
            )
            .trim(),
        'subject=CN=$profile',
      );
      expect(
        await fingerprintByOpenssl(bytes, 'req'),
        await fingerprintByOpenssl(utf8.encode(legacyKey), 'pkey'),
      );
      // Fresh keys too; RFC 6979 signing is deterministic per key and request.
      final key = await crypto.generateKey();
      final request = await crypto.certificationRequest(key, commonName: 'x');
      expect(await crypto.certificationRequest(key, commonName: 'x'), request);
      await openssl(['req', '-verify', '-noout'], utf8.encode(request));
      expect(
        keyFingerprint(crypto.requestPublicKeyInfo(request)),
        await fingerprintByOpenssl(utf8.encode(key), 'pkey'),
      );
    });

    group('certificates made by openssl', () {
      final issuers = <String, List<String>>{
        'issuer': ['-subj', '/CN=Fixture issuer'],
        // Same name as `issuer`, different key: only the signature tells.
        'impostor': ['-subj', '/CN=Fixture issuer'],
        'p384': ['-subj', '/CN=P-384 issuer', '-sha384'],
        'not-ca': [
          '-subj',
          '/CN=Not a CA',
          '-addext',
          'basicConstraints=critical,CA:FALSE',
        ],
        'no-cert-sign': [
          '-subj',
          '/CN=No certSign',
          '-addext',
          'keyUsage=critical,digitalSignature',
        ],
        'expired-issuer': [
          '-subj',
          '/CN=Expired issuer',
          '-not_before',
          '20200101000000Z',
          '-not_after',
          '20210101000000Z',
        ],
        'server-eku-issuer': [
          '-subj',
          '/CN=Server EKU issuer',
          '-addext',
          'extendedKeyUsage=serverAuth',
        ],
        'client-eku-issuer': [
          '-subj',
          '/CN=Client EKU issuer',
          '-addext',
          'extendedKeyUsage=clientAuth',
        ],
        // Non-critical directory constraints the leaf's CN=device violates
        // (the independent review's case).
        // The constraints come from config sections (-extensions): OpenSSL
        // 4 no longer resolves a dirName section named in -addext.
        'nc-violated': [
          '-subj',
          '/CN=Constrained issuer',
          '-config',
          'NC_CONFIG',
          '-extensions',
          'ext_nc_violated',
        ],
        // Constraints the leaf satisfies: OpenSSL accepts, we refuse.
        'nc-satisfied': [
          '-subj',
          '/CN=Device-constrained issuer',
          '-config',
          'NC_CONFIG',
          '-extensions',
          'ext_nc_satisfied',
        ],
        'nc-critical-satisfied': [
          '-subj',
          '/CN=Critically constrained issuer',
          '-config',
          'NC_CONFIG',
          '-extensions',
          'ext_nc_critical_satisfied',
        ],
        'rsa': ['-subj', '/CN=RSA issuer'],
      };
      late String csr;
      var serial = 1;

      Future<String> sign({
        String issuer = 'issuer',
        String extensions =
            'basicConstraints=critical,CA:FALSE\n'
            'keyUsage=critical,digitalSignature\n'
            'extendedKeyUsage=clientAuth\n',
        List<String> options = const ['-days', '30'],
      }) async {
        final out = path('leaf-${serial++}.crt');
        File(path('leaf.ext')).writeAsStringSync('[leaf]\n$extensions');
        await openssl([
          'x509',
          '-req',
          '-in',
          csr,
          '-CA',
          path('$issuer.crt'),
          '-CAkey',
          path('$issuer.key'),
          '-set_serial',
          '$serial',
          ...options,
          '-subj',
          '/CN=device',
          '-extfile',
          path('leaf.ext'),
          '-extensions',
          'leaf',
          '-out',
          out,
        ]);
        return File(out).readAsStringSync();
      }

      setUpAll(() async {
        const ca =
            'basicConstraints=critical,CA:TRUE,pathlen:0\n'
            'keyUsage=critical,keyCertSign,cRLSign\n';
        File(path('nc.cnf')).writeAsStringSync(
          '[req]\ndistinguished_name=dn\n[dn]\n'
          '[nc_other]\nCN=allowed\n[nc_device]\nCN=device\n'
          '[ext_nc_violated]\n${ca}nameConstraints=permitted;dirName:nc_other\n'
          '[ext_nc_satisfied]\n${ca}nameConstraints=permitted;dirName:nc_device\n'
          '[ext_nc_critical_satisfied]\n$ca'
          'nameConstraints=critical,permitted;dirName:nc_device\n',
        );
        for (final MapEntry(key: name, value: raw) in issuers.entries) {
          final options = [
            for (final o in raw) o == 'NC_CONFIG' ? path('nc.cnf') : o,
          ];
          final curve = name == 'p384' ? 'P-384' : 'P-256';
          // A config section (-extensions) carries its own CA extensions.
          final section = options.contains('-extensions');
          final constraints =
              section || options.contains('basicConstraints=critical,CA:FALSE')
              ? <String>[]
              : ['-addext', 'basicConstraints=critical,CA:TRUE,pathlen:0'];
          final usage = section || options.any((o) => o.startsWith('keyUsage'))
              ? <String>[]
              : ['-addext', 'keyUsage=critical,keyCertSign,cRLSign'];
          await openssl([
            'req',
            '-x509',
            '-newkey',
            if (name == 'rsa')
              'rsa:2048'
            else ...[
              'ec',
              '-pkeyopt',
              'ec_paramgen_curve:$curve',
            ],
            '-noenc',
            if (!options.contains('-not_after')) ...['-days', '365'],
            ...options,
            ...constraints,
            ...usage,
            '-keyout',
            path('$name.key'),
            '-out',
            path('$name.crt'),
          ]);
        }
        final key = await crypto.generateKey();
        csr = path('device.csr');
        File(csr).writeAsStringSync(
          await crypto.certificationRequest(key, commonName: 'device'),
        );
      });

      test(
        'expiry parsing equals openssl -enddate -dateopt iso_8601',
        () async {
          for (final end in [
            '20491231235959Z', // last UTCTime year
            '20500101000000Z', // first GeneralizedTime year
            '20380119031408Z',
            '20280229120000Z',
            '99991231235959Z',
          ]) {
            final pem = await sign(options: ['-not_after', end]);
            final line = utf8
                .decode(
                  await openssl([
                    'x509',
                    '-enddate',
                    '-noout',
                    '-dateopt',
                    'iso_8601',
                  ], utf8.encode(pem)),
                )
                .trim();
            expect(
              crypto.certificate(pem).notAfter,
              opensslDate(line.substring('notAfter='.length)),
              reason: end,
            );
          }
        },
      );

      test('client-chain accept/reject set equals openssl verify -purpose sslclient', () async {
        String tampered(String pem) {
          final der = Uint8List.fromList(pemBlocks(pem).single.$2);
          der[der.length - 1] ^= 0x01;
          return pemEncode('CERTIFICATE', der);
        }

        const leafBase = 'basicConstraints=critical,CA:FALSE\n';
        final cases = <String, (String, String, bool)>{
          // name: (leaf PEM, issuer file, expected acceptance)
          'valid client leaf': (await sign(), 'issuer', true),
          'serverAuth only': (
            await sign(
              extensions:
                  '${leafBase}keyUsage=critical,digitalSignature\nextendedKeyUsage=serverAuth\n',
            ),
            'issuer',
            false,
          ),
          'clientAuth and serverAuth': (
            await sign(
              extensions:
                  '${leafBase}keyUsage=critical,digitalSignature\nextendedKeyUsage=serverAuth,clientAuth\n',
            ),
            'issuer',
            true,
          ),
          'no extendedKeyUsage': (
            await sign(
              extensions: '${leafBase}keyUsage=critical,digitalSignature\n',
            ),
            'issuer',
            true,
          ),
          'keyUsage keyCertSign only': (
            await sign(
              extensions:
                  '${leafBase}keyUsage=critical,keyCertSign\nextendedKeyUsage=clientAuth\n',
            ),
            'issuer',
            false,
          ),
          'keyUsage keyAgreement': (
            await sign(
              extensions:
                  '${leafBase}keyUsage=critical,keyAgreement\nextendedKeyUsage=clientAuth\n',
            ),
            'issuer',
            true,
          ),
          'unknown critical extension': (
            await sign(
              extensions:
                  '${leafBase}extendedKeyUsage=clientAuth\n1.2.3.4=critical,ASN1:NULL\n',
            ),
            'issuer',
            false,
          ),
          'unknown non-critical extension': (
            await sign(
              extensions:
                  '${leafBase}extendedKeyUsage=clientAuth\n1.2.3.4=ASN1:NULL\n',
            ),
            'issuer',
            true,
          ),
          'critical subjectAltName': (
            await sign(
              extensions:
                  '${leafBase}extendedKeyUsage=clientAuth\nsubjectAltName=critical,DNS:device.invalid\n',
            ),
            'issuer',
            true,
          ),
          'expired leaf': (
            await sign(
              options: [
                '-not_before',
                '20200101000000Z',
                '-not_after',
                '20210101000000Z',
              ],
            ),
            'issuer',
            false,
          ),
          'not yet valid leaf': (
            await sign(
              options: [
                '-not_before',
                '20900101000000Z',
                '-not_after',
                '20910101000000Z',
              ],
            ),
            'issuer',
            false,
          ),
          'leaf marked CA (refused later by the pickup)': (
            await sign(
              extensions: 'basicConstraints=critical,CA:TRUE,pathlen:0\nkeyUsage=critical,digitalSignature\nextendedKeyUsage=clientAuth\n',
            ),
            'issuer',
            true,
          ),
          'SHA-512 signature': (
            await sign(options: ['-days', '30', '-sha512']),
            'issuer',
            true,
          ),
          'same-name impostor issuer': (
            await sign(issuer: 'impostor'),
            'issuer',
            false,
          ),
          'P-384 issuer, SHA-384': (
            await sign(issuer: 'p384', options: ['-days', '30', '-sha384']),
            'p384',
            true,
          ),
          'issuer not a CA': (await sign(issuer: 'not-ca'), 'not-ca', false),
          'issuer without keyCertSign': (
            await sign(issuer: 'no-cert-sign'),
            'no-cert-sign',
            false,
          ),
          'expired issuer': (
            await sign(issuer: 'expired-issuer'),
            'expired-issuer',
            false,
          ),
          'tampered signature': (tampered(await sign()), 'issuer', false),
          'issuer EKU serverAuth only': (
            await sign(issuer: 'server-eku-issuer'),
            'server-eku-issuer',
            false,
          ),
          'issuer EKU clientAuth': (
            await sign(issuer: 'client-eku-issuer'),
            'client-eku-issuer',
            true,
          ),
          'leaf nsCertType server': (
            await sign(
              extensions:
                  '${leafBase}keyUsage=critical,digitalSignature\nnsCertType=server\n',
            ),
            'issuer',
            false,
          ),
          'leaf nsCertType client': (
            await sign(
              extensions:
                  '${leafBase}keyUsage=critical,digitalSignature\nnsCertType=client\n',
            ),
            'issuer',
            true,
          ),
          'leaf nsCertType client and server': (
            await sign(
              extensions:
                  '${leafBase}keyUsage=critical,digitalSignature\nnsCertType=client,server\n',
            ),
            'issuer',
            true,
          ),
          'issuer nameConstraints, violated, non-critical': (
            await sign(issuer: 'nc-violated'),
            'nc-violated',
            false,
          ),
        };
        // Deliberately narrower than OpenSSL: refused here, accepted there.
        final narrower = <String, (String, String)>{
          'issuer nameConstraints, satisfied, non-critical': (
            await sign(issuer: 'nc-satisfied'),
            'nc-satisfied',
          ),
          'issuer nameConstraints, satisfied, critical': (
            await sign(issuer: 'nc-critical-satisfied'),
            'nc-critical-satisfied',
          ),
          'RSA issuer': (await sign(issuer: 'rsa'), 'rsa'),
        };
        Future<(bool, bool)> verdicts(String pem, String issuer) async {
          final leafFile = File(path('case.crt'))..writeAsStringSync(pem);
          final reference = await Process.run(opensslExecutable, [
            'verify',
            '-no-CApath',
            '-no-CAstore',
            '-CAfile',
            path('$issuer.crt'),
            '-purpose',
            'sslclient',
            leafFile.path,
          ]);
          var ours = true;
          try {
            await crypto.verifyClientCertificate(
              crypto.certificate(pem),
              crypto.certificates(File(path('$issuer.crt')).readAsStringSync()),
              at: DateTime.now().toUtc(),
            );
          } on FormatException {
            ours = false;
          }
          return (reference.exitCode == 0, ours);
        }

        for (final MapEntry(key: name, value: (pem, issuer, accept))
            in cases.entries) {
          final (reference, ours) = await verdicts(pem, issuer);
          expect(reference, accept, reason: 'openssl: $name');
          expect(ours, accept, reason: name);
        }
        for (final MapEntry(key: name, value: (pem, issuer))
            in narrower.entries) {
          expect(await verdicts(pem, issuer), (true, false), reason: name);
        }
      });
    });
  });

  test('malformed input is a FormatException, never a crash', () async {
    final good = pemBlocks(read('leaf_utc.crt')).single.$2;
    for (var cut = 0; cut < good.length; cut += 7) {
      expect(
        () => DeviceCertificate.fromDer(Uint8List.sublistView(good, 0, cut)),
        throwsFormatException,
      );
    }
    expect(
      () => DeviceCertificate.fromDer(Uint8List.fromList([...good, 0])),
      throwsFormatException,
    );
    // Indefinite (BER) length.
    expect(
      () => DeviceCertificate.fromDer(Uint8List.fromList([0x30, 0x80, 0, 0])),
      throwsFormatException,
    );
    expect(() => crypto.certificate('no PEM here'), throwsFormatException);
    await expectLater(
      crypto.publicKeyInfo(read('leaf_utc.crt')),
      throwsFormatException,
    );
    expect(
      () => crypto.requestPublicKeyInfo(read('issuer.crt')),
      throwsFormatException,
    );
  });
}
